package com.example.domain.model.i18n

internal object DuaGu1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("ઊંઘમાંથી જાગ્યા પછી", "બધી પ્રશંસા અલ્લાહ માટે છે, જેણે અમને મૃત્યુ (ઊંઘ) પછી જીવન આપ્યું, અને તેની તરફ જ પાછા ઊઠીને જવાનું છે.", "ઊંઘમાંથી જાગતાં જ અલ્લાહનો આભાર માનવા માટે.", "નબી ﷺ જાગીને આ દુઆ પઢતા — દિવસની શરૂઆત કૃતજ્ઞતા અને આખિરતની યાદથી."),
        "dua_leaving_home" to DuaText("ઘરેથી નીકળતી વખતે", "અલ્લાહના નામથી; મેં અલ્લાહ પર ભરોસો કર્યો. અલ્લાહ વિના કોઈ શક્તિ નથી અને કોઈ સામર્થ્ય નથી.", "ઘરની બહાર પગ મૂકતી વખતે અલ્લાહના રક્ષણ માટે.", "ફરિશ્તાઓ કહે છે: 'તને માર્ગદર્શન મળ્યું, તારી સંભાળ લેવાઈ અને તને બચાવી લેવાયો', અને શૈતાન દૂર થઈ જાય છે."),
        "dua_anxiety_distress" to DuaText("ચિંતા અને દુઃખમાંથી છુટકારો", "હે અલ્લાહ! હું ચિંતા અને દુઃખથી, નબળાઈ અને આળસથી, કંજૂસાઈ અને કાયરતાથી, દેવાના બોજ અને લોકોના વર્ચસ્વથી તારી પનાહ માગું છું.", "દુઃખ, ચિંતા, દેવાનો બોજ અને માનસિક તકલીફના સમયે.", "નબી ﷺ આ દુઆ વારંવાર કરતા — દુઃખ, આળસ અને દેવાની ચિંતાથી પનાહ."),
        "dua_sayyidul_istighfar" to DuaText("સય્યિદુલ ઇસ્તિગફાર", "હે અલ્લાહ! તું જ મારો રબ છે, તારા સિવા કોઈ પૂજ્ય નથી. તેં મને સર્જ્યો અને હું તારો બંદો છું, અને હું મારી શક્તિ મુજબ તારા વચન અને કરાર પર કાયમ છું. મારાં કર્મોની બૂરાઈથી હું તારી પનાહ માગું છું. મારા પરની તારી કૃપાઓ અને મારાં પાપોનો હું સ્વીકાર કરું છું, તેથી મને માફ કર, કારણ કે તારા સિવા કોઈ પાપ માફ કરતું નથી.", "સવાર અને સાંજ — નબી ﷺ એ શીખવેલી તૌબાની શ્રેષ્ઠ દુઆ.", "જે દૃઢ વિશ્વાસથી સાંજે પઢે અને એ જ રાત્રે મૃત્યુ પામે તે જન્નતમાં જશે; સવારે પઢવાની પણ આ જ ફઝીલત."),
        "dua_parents" to DuaText("માતા-પિતા માટે દુઆ", "હે મારા રબ! તે બંને પર દયા કર, જેમ તેમણે બાળપણમાં મારું પાલન-પોષણ કર્યું.", "માતા-પિતા માટે કુરઆની દુઆ — બાળપણના ઉછેરના બદલામાં.", "અલ્લાહે પોતે માતા-પિતા માટે આ દુઆ કરવાનો આદેશ આપ્યો."),
        "dua_entering_mosque" to DuaText("મસ્જિદમાં પ્રવેશ", "હે અલ્લાહ! મારા માટે તારી રહમતના દરવાજા ખોલી દે.", "જમણો પગ મૂકીને મસ્જિદમાં પ્રવેશતી વખતે.", "નબી ﷺ એ મસ્જિદમાં પ્રવેશતી વખતે આ દુઆ પઢવાનું શીખવ્યું."),
        "dua_morning_asbahna" to DuaText("સવારનો ઝિક્ર", "અમે સવાર કરી અને આખા રાજ્યએ પણ અલ્લાહ માટે સવાર કરી. બધી પ્રશંસા અલ્લાહ માટે છે. અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી. રાજ્ય તેનું જ છે, પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે.", "સવારે પઢવાની મસનૂન દુઆ.", "દિવસની શરૂઆત અલ્લાહના રાજ્ય અને તૌહીદના સ્વીકારથી થાય છે."),
        "dua_evening_amsayna" to DuaText("સાંજનો ઝિક્ર", "અમે સાંજ કરી અને આખા રાજ્યએ પણ અલ્લાહ માટે સાંજ કરી. બધી પ્રશંસા અલ્લાહ માટે છે. અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી. રાજ્ય તેનું જ છે, પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે.", "સાંજે પઢવાની મસનૂન દુઆ.", "રાત્રિની શરૂઆત અલ્લાહના રાજ્ય અને તૌહીદના સ્વીકારથી થાય છે."),
        "dua_bismillah_la_yadurru" to DuaText("દરેક નુકસાનથી રક્ષણ", "અલ્લાહના નામથી, જેના નામ સાથે ધરતી અને આકાશમાં કોઈ વસ્તુ નુકસાન પહોંચાડી શકતી નથી, અને તે સર્વ સાંભળનાર, સર્વ જાણનાર છે.", "સવાર અને સાંજ ત્રણ-ત્રણ વખત.", "જે સવાર-સાંજ ત્રણ વખત પઢે, તેને કોઈ વસ્તુ નુકસાન નહીં પહોંચાડે."),
        "dua_raditu_billahi" to DuaText("અલ્લાહને રબ તરીકે સંતુષ્ટ", "હું અલ્લાહને રબ તરીકે, ઇસ્લામને દીન તરીકે અને મુહમ્મદ ﷺ ને નબી તરીકે પામીને સંતુષ્ટ છું.", "સવાર અને સાંજ ત્રણ વખત.", "કયામતના દિવસે તેને સંતુષ્ટ કરવો અલ્લાહ પર તેનો હક બને છે."),
        "dua_hasbiyallah" to DuaText("હસ્બિયલ્લાહ (અલ્લાહ પૂરતો છે)", "મારા માટે અલ્લાહ પૂરતો છે, તેના સિવા કોઈ પૂજ્ય નથી, તેના પર જ મેં ભરોસો કર્યો અને તે મહાન અર્શનો રબ છે.", "સવાર અને સાંજ સાત વખત.", "કુરઆનની આયત; દુનિયા અને આખિરતની ચિંતાઓમાં અલ્લાહ પૂરતો થઈ જાય છે."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("સુબ્હાનલ્લાહિ વ બિહમ્દિહી", "અલ્લાહ પવિત્ર છે અને બધી પ્રશંસા તેની જ છે.", "દિવસમાં સો વખત.", "જે દિવસમાં સો વખત કહે, તેનાં પાપ માફ થાય છે ભલે તે સમુદ્રના ફીણ જેટલાં હોય."),
        "dua_tahleel_100" to DuaText("લા ઇલાહા ઇલ્લલ્લાહુ વહદહૂ", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી. રાજ્ય અને પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે.", "દિવસમાં સો વખત પઢવાની મોટી ફઝીલત.", "દસ ગુલામ આઝાદ કરવાનું પુણ્ય, સો નેકીઓ, સો પાપ માફ, અને સાંજ સુધી શૈતાનથી રક્ષણ."),
        "dua_leaving_mosque" to DuaText("મસ્જિદમાંથી નીકળતી વખતે", "હે અલ્લાહ! હું તારી પાસે તારી કૃપા માગું છું.", "ડાબો પગ બહાર મૂકીને મસ્જિદમાંથી નીકળતી વખતે.", "મસ્જિદમાંથી નીકળતાં અલ્લાહની કૃપા અને રોજીની માગણી."),
        "dua_after_adhan" to DuaText("અઝાન પછી", "હે અલ્લાહ! આ સંપૂર્ણ પોકાર અને કાયમ થનારી નમાઝના રબ! મુહમ્મદ ﷺ ને વસીલો અને શ્રેષ્ઠતા આપ, અને તેમને એ પ્રશંસિત સ્થાને પહોંચાડ જેનું તેં તેમને વચન આપ્યું છે.", "અઝાન પૂરી થયા પછી.", "જે આ દુઆ પઢે, કયામતના દિવસે તેના માટે નબી ﷺ ની શફાઅત નિશ્ચિત થઈ જાય છે."),
        "dua_after_salah_istighfar" to DuaText("ફર્ઝ નમાઝ પછી", "હું અલ્લાહ પાસે માફી માગું છું (૩ વખત). હે અલ્લાહ! તું જ સલામ છે અને તારાથી જ શાંતિ છે, તું બરકતવાળો છે હે મહિમા અને સન્માનના માલિક.", "સલામ ફેરવ્યા પછી તરત.", "નબી ﷺ દરેક ફર્ઝ નમાઝ પછી આ પઢતા."),
        "dua_after_salah_help_dhikr" to DuaText("તારા ઝિક્રમાં મારી મદદ કર", "હે અલ્લાહ! તારા ઝિક્ર, તારા આભાર અને તારી ઉત્તમ ઇબાદતમાં મારી મદદ કર.", "દરેક નમાઝ પછી — નબી ﷺ એ મુઆઝ (ર.) ને વસિયત કરી.", "નબી ﷺ ની ખાસ વસિયત — ઇબાદતમાં સુંદરતા અને નિયમિતતા."),
        "dua_ayatul_kursi" to DuaText("નમાઝ પછી આયતુલ કુર્સી", "અલ્લાહ, તેના સિવા કોઈ પૂજ્ય નથી, તે હંમેશા જીવંત, સૌનો આધાર છે. તેને ન ઊંઘ આવે છે ન ઝોકું. આકાશો અને ધરતીમાં જે કંઈ છે તે તેનું જ છે. કોણ છે જે તેની પરવાનગી વિના તેની પાસે ભલામણ કરે? તે જાણે છે જે તેમની આગળ અને પાછળ છે, અને તેઓ તેના જ્ઞાનમાંથી કશું જ ઘેરી શકતા નથી સિવાય કે જેટલું તે ઇચ્છે. તેની કુર્સી આકાશો અને ધરતીને ઘેરી વળેલી છે, અને તેમની રક્ષા તેને થકવતી નથી, તે સર્વોચ્ચ, મહાન છે.", "દરેક ફર્ઝ નમાઝ પછી અને સૂતાં પહેલાં.", "દરેક ફર્ઝ નમાઝ પછી પઢનારને જન્નતમાં જવાથી ફક્ત મૃત્યુ રોકે છે; સૂતાં પહેલાં પઢવાથી સવાર સુધી રક્ષણ."),
        "dua_before_sleep" to DuaText("સૂતાં પહેલાં", "હે અલ્લાહ! તારા જ નામથી હું મરું (સૂઉં) છું અને જીવું (જાગું) છું.", "પથારીમાં સૂઈ ગયા પછી.", "નબી ﷺ સૂતાં પહેલાં આ દુઆ પઢતા."),
        "dua_sleep_tasbeeh" to DuaText("સૂતાં પહેલાં તસ્બીહે ફાતિમી", "અલ્લાહ પવિત્ર છે (૩૩), બધી પ્રશંસા અલ્લાહ માટે છે (૩૩), અલ્લાહ સૌથી મહાન છે (૩૪).", "સૂતાં પહેલાં — નબી ﷺ એ ફાતિમા અને અલી (ર.) ને શીખવ્યું.", "નબી ﷺ એ ફરમાવ્યું કે આ તમારા માટે નોકર કરતાં ઉત્તમ છે."),
        "dua_sleep_qina_adhab" to DuaText("અઝાબથી રક્ષણ", "હે અલ્લાહ! જે દિવસે તું તારા બંદાઓને ઉઠાડીશ તે દિવસે મને તારા અઝાબથી બચાવ.", "જમણો હાથ ગાલ નીચે રાખીને ત્રણ વખત.", "ઊંઘને મૃત્યુની યાદ અને આખિરતની તૈયારી બનાવે છે."),
        "dua_bad_dream" to DuaText("ખરાબ સપનું જોયા પછી", "હું ધિક્કારાયેલા શૈતાનથી અલ્લાહની પનાહ માગું છું.", "ખરાબ સપનું જોયા પછી: ડાબી બાજુ ત્રણ વખત હળવું થૂંકો, પછી પડખું બદલો.", "ખરાબ સપનું નુકસાન નહીં કરે; કોઈને કહેશો નહીં."),
        "dua_yunus" to DuaText("યૂનુસ (અ.) ની દુઆ", "તારા સિવા કોઈ પૂજ્ય નથી, તું પવિત્ર છે, નિઃશંક હું જ અન્યાયીઓમાંથી હતો.", "માછલીના પેટમાં યૂનુસ (અ.) ની દુઆ — દરેક મુસીબતમાં.", "જે મુસ્લિમ કોઈ પણ બાબતમાં આ દુઆ કરે, અલ્લાહ તેની દુઆ કબૂલ કરે છે."),
        "dua_karb" to DuaText("સખત મુસીબતની દુઆ", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી જે મહાન, સહનશીલ છે. અલ્લાહ સિવા કોઈ પૂજ્ય નથી જે મહાન અર્શનો રબ છે. અલ્લાહ સિવા કોઈ પૂજ્ય નથી જે આકાશોનો રબ, ધરતીનો રબ અને સન્માનિત અર્શનો રબ છે.", "સખત મુસીબત અને તકલીફના સમયે.", "નબી ﷺ મુસીબતના સમયે આ દુઆ પઢતા."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("યા હય્યુ યા કય્યૂમ", "હે હંમેશા જીવંત, હે સૌના આધાર! તારી રહમતના વાસ્તે હું ફરિયાદ કરું છું.", "જ્યારે કોઈ બાબત ખૂબ ભારે થઈ જાય.", "કોઈ બાબત નબી ﷺ ને ચિંતિત કરતી ત્યારે તેઓ આ પઢતા."),
        "dua_hasbunallah" to DuaText("હસ્બુનલ્લાહુ વ નિઅમલ વકીલ", "અમારા માટે અલ્લાહ પૂરતો છે અને તે ઉત્તમ કાર્યસાધક છે.", "દુશ્મનના ડર કે મોટા જોખમના સમયે.", "ઇબ્રાહીમ (અ.) ને આગમાં નાખતી વખતે અને નબી ﷺ એ જોખમના સમયે આ કહ્યું."),
        "dua_entering_home" to DuaText("ઘરમાં પ્રવેશ", "અલ્લાહના નામથી.", "ઘરમાં પ્રવેશતી વખતે અલ્લાહનું નામ લો અને સલામ કરો.", "ઘરમાં પ્રવેશતાં અને જમતાં અલ્લાહનો ઝિક્ર કરવાથી શૈતાન કહે છે: અહીં તમારા માટે ન રાત વિતાવવાની જગ્યા છે ન ખાવાનું."),
        "dua_travel" to DuaText("મુસાફરી (સવારી) ની દુઆ", "પવિત્ર છે તે જેણે આને અમારા વશમાં કરી દીધું, નહીંતર અમે તેને વશમાં કરી શકતા ન હતા, અને નિઃશંક અમે અમારા રબ તરફ પાછા ફરનારા છીએ.", "સવારી પર બેસીને ત્રણ વખત અલ્લાહુ અકબર કહ્યા પછી.", "મુસાફરીની મસનૂન દુઆ — રક્ષણ અને બરકત માટે."),
        "dua_entering_market" to DuaText("બજારમાં પ્રવેશ", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી. રાજ્ય અને પ્રશંસા તેની જ છે. તે જ જીવન આપે છે અને મૃત્યુ આપે છે, અને તે પોતે હંમેશા જીવંત છે, કદી મરશે નહીં. તેના જ હાથમાં ભલાઈ છે અને તે દરેક વસ્તુ પર સમર્થ છે.", "બજારમાં પ્રવેશતી વખતે.", "હદીસમાં તેની મોટી ફઝીલત વર્ણવાઈ છે (લાખો નેકીઓ)."),
        "dua_adam_forgiveness" to DuaText("આદમ (અ.) ની દુઆ", "હે અમારા રબ! અમે અમારા પર જુલ્મ કર્યો, અને જો તું અમને માફ નહીં કરે અને અમારા પર દયા નહીં કરે તો અમે અવશ્ય નુકસાન ઉઠાવનારાઓમાંથી થઈ જઈશું.", "આદમ અને હવ્વા (અ.) ની તૌબાની દુઆ.", "માનવજાતની પ્રથમ તૌબા — અલ્લાહે તેને કબૂલ કરી."),
        "dua_abu_bakr" to DuaText("અબૂ બક્ર (ર.) ને શીખવેલી દુઆ", "હે અલ્લાહ! મેં મારા પર ઘણો જુલ્મ કર્યો છે, અને તારા સિવા કોઈ પાપ માફ કરતું નથી, તેથી તારી તરફથી મને માફ કર અને મારા પર દયા કર, નિઃશંક તું જ માફ કરનાર, દયાળુ છે.", "નમાઝમાં (તશહ્હુદ પછી) પઢવા માટે નબી ﷺ એ અબૂ બક્ર સિદ્દીક (ર.) ને શીખવી.", "નમાઝના અંતે પઢવાની મસનૂન દુઆ."),
        "dua_astaghfirullah_atubu" to DuaText("રોજિંદું ઇસ્તિગફાર", "હું અલ્લાહ પાસે માફી માગું છું અને તેની તરફ તૌબા કરું છું.", "નબી ﷺ દિવસમાં સિત્તેરથી વધુ વખત ઇસ્તિગફાર કરતા.", "નબી ﷺ એ ફરમાવ્યું: હું દિવસમાં સિત્તેરથી વધુ વખત અલ્લાહ પાસે માફી માગું છું અને તૌબા કરું છું."),
        "dua_laylatul_qadr" to DuaText("લૈલતુલ કદ્રની દુઆ", "હે અલ્લાહ! તું ખૂબ માફ કરનાર છે, માફીને પસંદ કરે છે, તેથી મને માફ કરી દે.", "આઇશા (ર.) ને લૈલતુલ કદ્ર માટે શીખવી.", "રમઝાનની છેલ્લી રાતો અને લૈલતુલ કદ્રની ખાસ દુઆ."),
        "dua_family_coolness" to DuaText("આંખોની ઠંડક (પત્ની-સંતાન)", "હે અમારા રબ! અમને અમારી પત્નીઓ અને સંતાનોથી આંખોની ઠંડક આપ, અને અમને પરહેઝગારોના ઇમામ બનાવ.", "નેક પત્ની/પતિ અને સંતાન માટે કુરઆની દુઆ.", "ઘરમાં શાંતિ અને નેક સંતાન માટે."),
        "dua_righteous_children" to DuaText("નેક સંતાન માટે", "હે મારા રબ! તારી પાસેથી મને પવિત્ર સંતાન આપ, નિઃશંક તું દુઆ સાંભળનાર છે.", "ઝકરિયા (અ.) ની દુઆ.", "સંતાન માગવા માટે કુરઆની દુઆ."),
        "dua_ibrahim_prayer_family" to DuaText("નમાઝ કાયમ કરનારા", "હે મારા રબ! મને અને મારી સંતાનને નમાઝ કાયમ કરનાર બનાવ. હે અમારા રબ! મારી દુઆ કબૂલ કર. હે અમારા રબ! હિસાબના દિવસે મને, મારાં માતા-પિતાને અને બધા મોમિનોને માફ કર.", "ઇબ્રાહીમ (અ.) ની પોતાના અને સંતાન માટે દુઆ.", "સામાન્ય રીતે નમાઝના અંતે પઢાય છે."),
        "dua_newlywed" to DuaText("નવદંપતીને અભિનંદન", "અલ્લાહ તમારા માટે બરકત આપે, તમારા પર બરકત ઉતારે અને તમને બંનેને ભલાઈમાં એક રાખે.", "નિકાહ કરનારને અભિનંદન આપતી વખતે.", "નિકાહના મસનૂન અભિનંદન."),
        "dua_before_eating" to DuaText("જમતાં પહેલાં", "અલ્લાહના નામથી. (ભૂલી જવાય તો:) અલ્લાહના નામથી, તેની શરૂઆતમાં અને અંતમાં.", "જમતાં પહેલાં. ભૂલી જાઓ તો વચ્ચે પઢો.", "બિસ્મિલ્લાહ પઢવાથી ખાવામાં શૈતાન ભાગીદાર થતો નથી."),
        "dua_after_eating" to DuaText("જમ્યા પછી", "બધી પ્રશંસા અલ્લાહ માટે જેણે મને આ ખવડાવ્યું અને મારી કોઈ શક્તિ અને સામર્થ્ય વિના મને આ રોજી આપી.", "જમવાનું પૂરું કર્યા પછી.", "પઢનારનાં અગાઉનાં પાપ માફ થઈ જાય છે."),
        "dua_host" to DuaText("યજમાન માટે", "હે અલ્લાહ! તેં તેમને જે રોજી આપી છે તેમાં બરકત આપ, તેમને માફ કર અને તેમના પર દયા કર.", "કોઈને ત્યાં જમ્યા પછી યજમાન માટે.", "મસનૂન રીતે યજમાનનો આભાર."),
        "dua_breaking_fast" to DuaText("રોઝો ખોલતી વખતે", "તરસ છીપાઈ, નસો ભીની થઈ અને અલ્લાહ ઇચ્છે તો સવાબ નિશ્ચિત થયો.", "ઇફ્તારના સમયે.", "નબી ﷺ ઇફ્તારના સમયે આ ફરમાવતા."),
        "dua_new_clothes" to DuaText("નવાં કપડાં પહેરતી વખતે", "હે અલ્લાહ! બધી પ્રશંસા તારા માટે છે, તેં જ મને આ પહેરાવ્યું. હું તારી પાસે તેની ભલાઈ અને જે હેતુ માટે તે બન્યું છે તેની ભલાઈ માગું છું, અને તેની બૂરાઈ અને જે હેતુ માટે બન્યું છે તેની બૂરાઈથી તારી પનાહ માગું છું.", "નવું કપડું પહેરતી વખતે (કપડાનું નામ લઈને, જેમ કે કુર્તો કે પાઘડી).", "નબી ﷺ નવું કપડું પહેરતા ત્યારે આ દુઆ કરતા. (રોજ કપડાં પહેરવાની દુઆ 'કપડાં પહેરવાં' માં છે.)"),
        "dua_rabbana_atina" to DuaText("દુનિયા અને આખિરતની ભલાઈ", "હે અમારા રબ! અમને દુનિયામાં પણ ભલાઈ આપ અને આખિરતમાં પણ ભલાઈ આપ, અને અમને આગના અઝાબથી બચાવ.", "નબી ﷺ સૌથી વધુ આ દુઆ કરતા.", "દુનિયા અને આખિરતની દરેક ભલાઈ ભેગી કરતી દુઆ."),
        "dua_rabbi_zidni_ilma" to DuaText("જ્ઞાનમાં વધારો", "હે મારા રબ! મારા જ્ઞાનમાં વધારો કર.", "જ્ઞાનમાં વધારા માટે.", "અલ્લાહે નબી ﷺ ને ફક્ત જ્ઞાનમાં વધારાની દુઆ કરવાનો આદેશ આપ્યો."),
        "dua_musa_sharh_sadr" to DuaText("છાતી ખોલવાની દુઆ (મૂસા અ.)", "હે મારા રબ! મારી છાતી ખોલી દે, મારું કામ આસાન કરી દે, અને મારી જીભની ગાંઠ ખોલી દે જેથી લોકો મારી વાત સમજી શકે.", "પરીક્ષા, ભાષણ કે કોઈ મુશ્કેલ કામ પહેલાં.", "મૂસા (અ.) ની દુઆ — દિલની શાંતિ અને કામમાં સરળતા."),
        "dua_la_tuzigh" to DuaText("દિલની દૃઢતા", "હે અમારા રબ! અમને માર્ગદર્શન આપ્યા પછી અમારાં દિલોને વાંકાં ન કર, અને અમને તારી પાસેથી રહમત આપ, નિઃશંક તું જ ખૂબ આપનાર છે.", "માર્ગદર્શન પર દૃઢ રહેવા માટે.", "ઈમાન પર દૃઢ રહેવાની દુઆ."),
        "dua_ya_muqallib" to DuaText("હે દિલો ફેરવનાર", "હે દિલો ફેરવનાર! મારા દિલને તારા દીન પર દૃઢ રાખ.", "નબી ﷺ ઘણી વાર આ દુઆ કરતા.", "ઉમ્મે સલમા (ર.) મુજબ નબી ﷺ ની સૌથી વધુ કરાતી દુઆ."),
        "dua_la_tuakhidhna" to DuaText("સૂરહ બકરાની છેલ્લી આયતો", "હે અમારા રબ! જો અમે ભૂલી જઈએ કે ભૂલ કરીએ તો અમારી પકડ ન કર. હે અમારા રબ! અમારા પર એવો બોજ ન નાખ જેવો અમારા પહેલાંના લોકો પર નાખ્યો. હે અમારા રબ! અમારા પર એ બોજ ન નાખ જેની અમારામાં શક્તિ નથી. અમને માફ કર, બખ્શી દે અને અમારા પર દયા કર. તું જ અમારો સ્વામી છે, તેથી કાફિર કોમ સામે અમારી મદદ કર.", "રાત્રે સૂતાં પહેલાં — સૂરહ બકરાની છેલ્લી બે આયતો.", "જે રાત્રે સૂરહ બકરાની છેલ્લી બે આયતો પઢે, તે તેના માટે પૂરતી થઈ જાય છે."),
        "dua_visiting_sick" to DuaText("બીમારની મુલાકાત", "હું મહાન અલ્લાહ પાસે, જે મહાન અર્શનો રબ છે, પ્રાર્થના કરું છું કે તને સાજો કરે.", "બીમારની મુલાકાત વખતે સાત વખત.", "જો મૃત્યુનો સમય ન આવ્યો હોય તો અલ્લાહ તેને સાજો કરી દે છે."),
        "dua_ruqyah_pain" to DuaText("શરીરના દુખાવા માટે", "હું અલ્લાહ અને તેની કુદરતની પનાહ માગું છું એ તકલીફની બૂરાઈથી જે હું અનુભવું છું અને જેનો મને ડર છે.", "દુખાવાની જગ્યાએ હાથ મૂકીને ત્રણ વખત બિસ્મિલ્લાહ, પછી સાત વખત આ દુઆ.", "નબી ﷺ એ ઉસ્માન બિન અબિલ આસ (ર.) ને દુખાવા માટે શીખવી."),
        "dua_ruqyah_nabawi" to DuaText("બીમાર માટે નબવી રુક્યા", "હે અલ્લાહ, લોકોના રબ! તકલીફ દૂર કર, સાજો કર, તું જ સાજો કરનાર છે, તારી શિફા સિવા કોઈ શિફા નથી, એવી શિફા જે કોઈ બીમારી બાકી ન રાખે.", "બીમાર પર હાથ ફેરવીને.", "નબી ﷺ પોતાના પરિવારના બીમારોની મુલાકાતમાં આ પઢતા."),
        "dua_kalimat_tammat" to DuaText("સંપૂર્ણ કલિમાતની પનાહ", "હું અલ્લાહના સંપૂર્ણ કલિમાતની પનાહ માગું છું તેણે સર્જેલી દરેક વસ્તુની બૂરાઈથી.", "કોઈ જગ્યાએ પડાવ કરતી વખતે કે સાંજે.", "જે કોઈ જગ્યાએ ઊતરીને આ પઢે, ત્યાંથી જાય ત્યાં સુધી કોઈ વસ્તુ તેને નુકસાન નહીં કરે."),
        "dua_evil_eye" to DuaText("બાળકોનું રક્ષણ (નજર)", "હું તમને બંનેને અલ્લાહના સંપૂર્ણ કલિમાતની પનાહમાં આપું છું દરેક શૈતાન અને ઝેરી જાનવરથી, અને દરેક નુકસાનકારક નજરથી.", "નબી ﷺ હસન અને હુસૈન (ર.) પર આ ફૂંકતા.", "બાળકોને નજર અને બૂરાઈથી બચાવવાની મસનૂન દુઆ (એક બાળક માટે 'ઉઈઝુકા')."),
        "dua_seeing_afflicted" to DuaText("કોઈને મુસીબતમાં જોઈને", "બધી પ્રશંસા અલ્લાહ માટે જેણે મને તેનાથી સુરક્ષિત રાખ્યો જેમાં તને આઝમાવ્યો, અને મને તેની ઘણી સૃષ્ટિ પર શ્રેષ્ઠતા આપી.", "કોઈને મુસીબતમાં જોઈને (મનમાં પઢો).", "પઢનાર એ મુસીબતથી સુરક્ષિત રહે છે."),
        "dua_istikhara" to DuaText("સલાતુલ ઇસ્તિખારા", "હે અલ્લાહ! હું તારા જ્ઞાન દ્વારા તારી પાસે ભલાઈ માગું છું, તારી કુદરત દ્વારા શક્તિ માગું છું, અને તારી મહાન કૃપાનો સવાલ કરું છું. તું સમર્થ છે હું નથી, તું જાણે છે હું નથી જાણતો, અને તું અદૃશ્યનો પૂર્ણ જાણનાર છે. હે અલ્લાહ! જો તારા જ્ઞાનમાં આ કામ (પોતાનું કામ મનમાં લાવો) મારા દીન, મારા જીવન અને પરિણામ માટે સારું હોય તો તેને મારા માટે નક્કી કર, આસાન કર અને પછી તેમાં બરકત આપ. અને જો તારા જ્ઞાનમાં આ કામ મારા દીન, જીવન અને પરિણામ માટે ખરાબ હોય તો તેને મારાથી અને મને તેનાથી ફેરવી દે, અને જ્યાં પણ ભલાઈ હોય તે મારા માટે નક્કી કર, પછી મને તેના પર રાજી કરી દે.", "કોઈ જાઈઝ કામમાં ભલાઈ માગવા બે રકાત નફલ પછી.", "નબી ﷺ સહાબાને દરેક કામમાં ઇસ્તિખારા કુરઆનની સૂરહની જેમ શીખવતા."),
        "dua_allahumma_bika_asbahna" to DuaText("અલ્લાહુમ્મા બિકા અસબહના", "હે અલ્લાહ! તારી જ મદદથી અમે સવાર કરી અને તારી જ મદદથી સાંજ કરી, તારા જ હુકમથી જીવીએ છીએ અને મરીએ છીએ, અને તારી જ તરફ ઊઠીને જવાનું છે.", "સવારે.", "નબી ﷺ સહાબાને સવાર-સાંજ આ શીખવતા."),
        "dua_allahumma_bika_amsayna" to DuaText("અલ્લાહુમ્મા બિકા અમસૈના", "હે અલ્લાહ! તારી જ મદદથી અમે સાંજ કરી અને તારી જ મદદથી સવાર કરી, તારા જ હુકમથી જીવીએ છીએ અને મરીએ છીએ, અને તારી જ તરફ પાછા ફરવાનું છે.", "સાંજે.", "નબી ﷺ સહાબાને સવાર-સાંજ આ શીખવતા."),
        "dua_afiyah_morning" to DuaText("આફિયતની દુઆ", "હે અલ્લાહ! હું તારી પાસે દુનિયા અને આખિરતમાં માફી અને સલામતી માગું છું.", "નબી ﷺ સવાર-સાંજ આ દુઆ કદી છોડતા નહીં.", "સલામતીથી ઉત્તમ કોઈ વસ્તુ કોઈને આપવામાં આવી નથી."),
        "dua_afini_fi_badani" to DuaText("શરીર, સાંભળવા અને જોવાની તંદુરસ્તી", "હે અલ્લાહ! મારા શરીરમાં સલામતી આપ, મારી સાંભળવાની શક્તિમાં સલામતી આપ, મારી દૃષ્ટિમાં સલામતી આપ. તારા સિવા કોઈ પૂજ્ય નથી.", "સવાર અને સાંજ ત્રણ-ત્રણ વખત.", "તંદુરસ્તી અને ઇન્દ્રિયોના રક્ષણની દુઆ."),
        "dua_ya_hayyu_aslih" to DuaText("મારાં બધાં કામ સુધારી દે", "હે હંમેશા જીવંત, હે આધાર! તારી રહમતથી ફરિયાદ કરું છું, મારાં બધાં કામ સુધારી દે અને મને પલક ઝપકવા જેટલો પણ મારા મનના હવાલે ન કર.", "નબી ﷺ એ ફાતિમા (ર.) ને સવાર-સાંજ પઢવાની વસિયત કરી.", "દરેક કામમાં અલ્લાહની મદદની માગણી."),
        "dua_subhanallah_adada_khalqihi" to DuaText("જુવૈરિયા (ર.) ની તસ્બીહ", "અલ્લાહ પવિત્ર છે અને પ્રશંસા તેની જ છે — તેની સૃષ્ટિની ગણતરી જેટલી, તેની પ્રસન્નતા મુજબ, તેના અર્શના વજન જેટલી અને તેના કલિમાતની શાહી જેટલી.", "સવારે ત્રણ વખત — કલાકોના ઝિક્રથી ભારે.", "આ ચાર વાક્યો ત્રણ વખત કહેવાં સવારથી બપોર સુધીના ઝિક્રથી વજનમાં ભારે છે."),
        "dua_salawat" to DuaText("દુરૂદે ઇબ્રાહીમી", "હે અલ્લાહ! મુહમ્મદ ﷺ અને મુહમ્મદના પરિવાર પર રહમત ઉતાર જેમ તેં ઇબ્રાહીમ (અ.) અને ઇબ્રાહીમના પરિવાર પર ઉતારી, નિઃશંક તું પ્રશંસનીય, ગૌરવશાળી છે. હે અલ્લાહ! મુહમ્મદ ﷺ અને મુહમ્મદના પરિવાર પર બરકત ઉતાર જેમ તેં ઇબ્રાહીમ (અ.) અને ઇબ્રાહીમના પરિવાર પર ઉતારી, નિઃશંક તું પ્રશંસનીય, ગૌરવશાળી છે.", "નમાઝમાં અને દરેક સમયે નબી ﷺ પર દુરૂદ.", "જે એક વખત દુરૂદ મોકલે, અલ્લાહ તેના પર દસ રહમતો ઉતારે છે (મુસ્લિમ ૪૦૮)."),
        "dua_wudu_after" to DuaText("વુઝૂ પછી", "હું ગવાહી આપું છું કે અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, અને મુહમ્મદ ﷺ તેના બંદા અને રસૂલ છે. હે અલ્લાહ! મને તૌબા કરનારાઓ અને પવિત્ર રહેનારાઓમાંથી બનાવ.", "વુઝૂ પૂર્ણ કર્યા પછી.", "જન્નતના આઠેય દરવાજા ખોલી દેવાય છે, જેમાંથી ચાહે પ્રવેશે."),
        "dua_wudu_before" to DuaText("વુઝૂ પહેલાં", "અલ્લાહના નામથી.", "વુઝૂ શરૂ કરતી વખતે.", "જેણે વુઝૂ પર અલ્લાહનું નામ ન લીધું તેનું વુઝૂ (સંપૂર્ણ) નથી."),
        "dua_istiftah" to DuaText("સના (નમાઝની શરૂઆતની દુઆ)", "હે અલ્લાહ! તું પવિત્ર છે તારી પ્રશંસા સાથે, તારું નામ બરકતવાળું છે, તારી શાન ઊંચી છે અને તારા સિવા કોઈ પૂજ્ય નથી.", "નમાઝ શરૂ કરતી વખતે, તકબીરે તહરીમા પછી તરત.", "નમાઝની મસનૂન શરૂઆતની દુઆ."),
        "dua_ruku" to DuaText("રુકૂમાં", "મારો મહાન રબ પવિત્ર છે.", "રુકૂમાં ઓછામાં ઓછું ત્રણ વખત.", "રુકૂની મસનૂન તસ્બીહ."),
        "dua_sujood" to DuaText("સિજદામાં", "મારો સર્વોચ્ચ રબ પવિત્ર છે.", "સિજદામાં ઓછામાં ઓછું ત્રણ વખત.", "બંદો સિજદામાં પોતાના રબની સૌથી નજીક હોય છે (મુસ્લિમ ૪૮૨)."),
        "dua_rising_ruku" to DuaText("રુકૂમાંથી ઊઠતી વખતે", "જેણે અલ્લાહની પ્રશંસા કરી અલ્લાહે તેની સાંભળી. હે અમારા રબ! બધી પ્રશંસા તારા માટે જ છે.", "રુકૂમાંથી ઊઠતાં અને સીધા ઊભા થઈને.", "જેનું 'રબ્બના વ લકલ હમ્દ' ફરિશ્તાઓ સાથે મળી ગયું તેનાં અગાઉનાં પાપ માફ."),
        "dua_between_sajdas" to DuaText("બે સિજદા વચ્ચે", "હે મારા રબ! મને માફ કર, હે મારા રબ! મને માફ કર.", "બે સિજદા વચ્ચે બેઠા હોય ત્યારે.", "જલ્સાની મસનૂન દુઆ."),
        "dua_before_salam_four" to DuaText("ચાર વસ્તુઓથી પનાહ (સલામ પહેલાં)", "હે અલ્લાહ! હું તારી પનાહ માગું છું જહન્નમના અઝાબથી, કબરના અઝાબથી, જીવન અને મૃત્યુના ફિતનાથી, અને મસીહ દજ્જાલના ફિતનાની બૂરાઈથી.", "છેલ્લા તશહ્હુદ અને દુરૂદ પછી, સલામ પહેલાં.", "નબી ﷺ એ આ ચાર વસ્તુઓથી પનાહ માગવાનો આદેશ આપ્યો."),
        "dua_qunoot_witr" to DuaText("વિત્રમાં કુનૂત", "હે અલ્લાહ! જેમને તેં માર્ગદર્શન આપ્યું તેમનામાં મને માર્ગદર્શન આપ, જેમને સલામતી આપી તેમનામાં મને સલામતી આપ, જેમની સંભાળ લીધી તેમનામાં મારી સંભાળ લે, જે આપ્યું તેમાં બરકત આપ, અને જે ફેંસલો કર્યો તેની બૂરાઈથી બચાવ. નિઃશંક તું ફેંસલો કરે છે અને તારી વિરુદ્ધ ફેંસલો થતો નથી, અને જેનો તું મિત્ર હોય તે અપમાનિત થતો નથી. હે અમારા રબ! તું બરકતવાળો અને ઉચ્ચ છે.", "વિત્રની નમાઝમાં — નબી ﷺ એ હસન બિન અલી (ર.) ને શીખવી.", "વિત્રની મસનૂન કુનૂત. (હનફીઓમાં 'અલ્લાહુમ્મા ઇન્ના નસ્તઈનુકા' પણ પ્રચલિત છે.)"),
        "dua_qunoot_hanafi" to DuaText("કુનૂત (અલ્લાહુમ્મા ઇન્ના નસ્તઈનુકા)", "હે અલ્લાહ! અમે તારી પાસે મદદ અને માફી માગીએ છીએ, તારા પર ઈમાન લાવીએ છીએ અને ભરોસો કરીએ છીએ, તારી ઉત્તમ પ્રશંસા કરીએ છીએ, તારો આભાર માનીએ છીએ, નાશુક્રી કરતા નથી, અને જે તારી નાફરમાની કરે તેને છોડીએ છીએ. હે અલ્લાહ! અમે તારી જ ઇબાદત કરીએ છીએ, તારા માટે જ નમાઝ પઢીએ છીએ અને સિજદો કરીએ છીએ, તારી તરફ દોડીએ છીએ, તારી રહમતની આશા રાખીએ છીએ અને તારા અઝાબથી ડરીએ છીએ; નિઃશંક તારો અઝાબ કાફિરોને પહોંચનાર છે.", "વિત્રમાં — હનફીઓનો અમલ.", "ઉમર (ર.) થી કુનૂતમાં વર્ણવાયેલી."),
        "dua_sleep_aslamtu" to DuaText("સૂતાં પહેલાંના છેલ્લા શબ્દો", "હે અલ્લાહ! મેં મારી જાતને તને સોંપી, મારું કામ તારા હવાલે કર્યું, મારી પીઠ તારી પનાહમાં આપી, તારી આશા અને તારા ડર સાથે. તારાથી બચવાની કોઈ પનાહ અને મુક્તિ નથી તારી તરફ સિવાય. હું તારી ઉતારેલી કિતાબ અને તારા મોકલેલા નબી પર ઈમાન લાવ્યો.", "વુઝૂ કરીને જમણા પડખે સૂઈને — સૌથી છેલ્લી વાત.", "જો એ જ રાત્રે મૃત્યુ આવે તો ફિતરત (ઇસ્લામ) પર મૃત્યુ થશે."),
        "dua_waking_night" to DuaText("રાત્રે આંખ ખૂલે ત્યારે", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, રાજ્ય અને પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે. બધી પ્રશંસા અલ્લાહ માટે, અલ્લાહ પવિત્ર છે, અલ્લાહ સિવા કોઈ પૂજ્ય નથી, અલ્લાહ સૌથી મહાન છે, અને અલ્લાહ વિના ન કોઈ શક્તિ છે ન સામર્થ્ય. હે અલ્લાહ! મને માફ કર.", "રાત્રે આંખ ખૂલે ત્યારે.", "દુઆ કબૂલ થાય છે, અને વુઝૂ કરીને નમાઝ પઢે તો નમાઝ કબૂલ થાય છે."),
        "dua_hamm_ibn_masud" to DuaText("દુઃખની દુઆ (ઇબ્ને મસઊદ)", "હે અલ્લાહ! હું તારો બંદો છું, તારા બંદાનો દીકરો, તારી બાંદીનો દીકરો. મારું કપાળ તારા હાથમાં છે, મારા પર તારો હુકમ ચાલે છે, મારા વિશે તારો ફેંસલો ન્યાયપૂર્ણ છે. હું તારા દરેક એ નામના વાસ્તે તારી પાસે સવાલ કરું છું જે તેં પોતાનું રાખ્યું, અથવા તારી કિતાબમાં ઉતાર્યું, અથવા તારી કોઈ સૃષ્ટિને શીખવ્યું, અથવા તારી પાસે અદૃશ્ય જ્ઞાનમાં સુરક્ષિત રાખ્યું — કે કુરઆનને મારા દિલની વસંત, મારી છાતીનો પ્રકાશ, મારા દુઃખનો ઇલાજ અને મારી ચિંતા દૂર કરનાર બનાવી દે.", "દુઃખ અને ચિંતામાં — અલ્લાહ દુઃખને ખુશીમાં બદલી દે છે.", "અલ્લાહ તેની ચિંતા અને દુઃખ દૂર કરીને ખુશી આપે છે."),
        "dua_difficulty_sahl" to DuaText("જ્યારે કોઈ કામ મુશ્કેલ હોય", "હે અલ્લાહ! કોઈ વસ્તુ આસાન નથી સિવાય કે જેને તું આસાન કરે, અને તું ચાહે ત્યારે મુશ્કેલને આસાન કરી દે છે.", "કોઈ કામ મુશ્કેલ લાગે ત્યારે.", "પરીક્ષા અને મુશ્કેલ કામોમાં સરળતા."),
        "dua_musibah" to DuaText("મુસીબત પર (ઇસ્તિરજા)", "અમે અલ્લાહના જ છીએ અને તેની તરફ જ પાછા ફરનારા છીએ. હે અલ્લાહ! મારી મુસીબતમાં મને સવાબ આપ અને તેનાથી ઉત્તમ બદલો આપ.", "કોઈ પણ નુકસાન કે મુસીબત પર.", "અલ્લાહ અવશ્ય ઉત્તમ બદલો આપે છે — ઉમ્મે સલમા (ર.) ને નબી ﷺ મળ્યા."),
        "dua_debt" to DuaText("દેવામાંથી છુટકારા માટે", "હે અલ્લાહ! તારા હલાલ દ્વારા મને હરામથી બચાવીને પૂરતો થઈ જા, અને તારી કૃપાથી મને તારા સિવા બધાથી બેનિયાઝ કરી દે.", "દેવું ચૂકવવા માટે — અલી (ર.) એ શીખવી.", "પહાડ જેટલું દેવું હોય તો પણ અલ્લાહ ચૂકવાવી દે છે."),
        "dua_anger" to DuaText("ગુસ્સાના સમયે", "હું ધિક્કારાયેલા શૈતાનથી અલ્લાહની પનાહ માગું છું.", "ગુસ્સો આવે ત્યારે.", "નબી ﷺ એ ફરમાવ્યું: જો તે આ કહી દે તો તેનો ગુસ્સો ચાલ્યો જાય."),
        "dua_waswasa" to DuaText("ઈમાનમાં વસવસા સામે", "હું અલ્લાહ અને તેના રસૂલો પર ઈમાન લાવ્યો.", "ઈમાન વિશે શૈતાની વસવસા આવે ત્યારે.", "વસવસો આવે તો આ કહે અને રોકાઈ જાય (અઊઝુ બિલ્લાહ પણ પઢે)."),
        "dua_travel_full" to DuaText("મુસાફરીની સંપૂર્ણ દુઆ", "હે અલ્લાહ! અમે આ મુસાફરીમાં તારી પાસે નેકી અને તકવા માગીએ છીએ અને એવો અમલ જે તને પસંદ હોય. હે અલ્લાહ! અમારી આ મુસાફરી અમારા માટે આસાન કરી દે અને તેનું અંતર ટૂંકું કરી દે. હે અલ્લાહ! તું જ મુસાફરીનો સાથી અને પરિવારનો રખેવાળ છે.", "મુસાફરીએ નીકળતી વખતે, 'સુબ્હાનલ્લઝી સખ્ખરા' પછી.", "મુસાફરીની સંપૂર્ણ મસનૂન દુઆ."),
        "dua_return_travel" to DuaText("મુસાફરીમાંથી પાછા ફરતાં", "અમે પાછા ફરનારા, તૌબા કરનારા, ઇબાદત કરનારા અને અમારા રબની પ્રશંસા કરનારા છીએ.", "મુસાફરીમાંથી પાછા ફરતી વખતે.", "નબી ﷺ મુસાફરીમાંથી પાછા ફરતાં આ ફરમાવતા."),
        "dua_farewell_traveller" to DuaText("મુસાફરને વિદાય", "હું તારો દીન, તારી અમાનત અને તારાં કર્મોનો અંજામ અલ્લાહને સોંપું છું.", "મુસાફરને વિદાય આપતી વખતે.", "અલ્લાહને સોંપેલી વસ્તુ વેડફાતી નથી."),
        "dua_entering_town" to DuaText("કોઈ જગ્યાએ રોકાણ", "હું અલ્લાહના સંપૂર્ણ કલિમાતની પનાહ માગું છું તેની દરેક સૃષ્ટિની બૂરાઈથી.", "કોઈ જગ્યાએ પડાવ કે નવા શહેરમાં પહોંચીને.", "ત્યાંથી રવાના થાય ત્યાં સુધી કોઈ વસ્તુ નુકસાન નહીં કરે."),
        "dua_boarding_ship" to DuaText("વહાણ/વાહનમાં બેસતી વખતે", "અલ્લાહના નામથી જ તેનું ચાલવું અને થોભવું છે, નિઃશંક મારો રબ માફ કરનાર, દયાળુ છે.", "વહાણ કે વાહનમાં બેસતી વખતે — નૂહ (અ.) નું કથન.", "કુરઆની આયત — નૂહ (અ.) ના વહાણની દુઆ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("હય્યુલ કય્યૂમ સાથે ઇસ્તિગફાર", "હું તે અલ્લાહ પાસે માફી માગું છું જેના સિવા કોઈ પૂજ્ય નથી, જે હંમેશા જીવંત અને આધાર છે, અને તેની તરફ તૌબા કરું છું.", "તૌબા માટે.", "પાપ માફ થઈ જાય છે ભલે યુદ્ધના મેદાનમાંથી ભાગ્યો હોય."),
        "dua_rabbighfir_warham" to DuaText("રબ્બિગફિર વરહમ", "હે મારા રબ! માફ કર અને દયા કર, અને તું સૌથી ઉત્તમ દયા કરનાર છે.", "કુરઆની દુઆ — માફી અને રહમત.", "સૂરહ મોમિનૂનની છેલ્લી આયત."),
        "dua_majlis_kaffarah" to DuaText("મજલિસનો કફ્ફારો", "હે અલ્લાહ! તું પવિત્ર છે તારી પ્રશંસા સાથે. હું ગવાહી આપું છું કે તારા સિવા કોઈ પૂજ્ય નથી. હું તારી પાસે માફી માગું છું અને તારી તરફ તૌબા કરું છું.", "મજલિસ/બેઠકમાંથી ઊઠતી વખતે.", "મજલિસમાં જે ખોટી વાતો થઈ તેનો કફ્ફારો બની જાય છે."),
        "dua_jami_forgiveness" to DuaText("વ્યાપક માફી", "હે અલ્લાહ! મારી ભૂલ, મારી અજ્ઞાનતા, મારા કામમાં મારી અતિશયોક્તિ, અને જે તું મારા કરતાં વધુ જાણે છે તે બધું માફ કરી દે.", "નબી ﷺ ની વ્યાપક દુઆ.", "નબી ﷺ આ દુઆ કરતા."),
        "dua_parents_nuh" to DuaText("માતા-પિતા માટે નૂહ (અ.) ની દુઆ", "હે મારા રબ! મને, મારાં માતા-પિતાને, જે ઈમાન સાથે મારા ઘરમાં પ્રવેશે તેને, અને બધા મોમિન પુરુષો અને સ્ત્રીઓને માફ કર.", "માતા-પિતા અને મોમિનો માટે.", "નૂહ (અ.) ની દુઆ."),
        "dua_shukr_parents" to DuaText("માતા-પિતાની કૃપાનો આભાર અને નેક સંતાન", "હે મારા રબ! મને તૌફીક આપ કે હું તારી એ કૃપાનો આભાર માનું જે તેં મારા પર અને મારાં માતા-પિતા પર કરી, અને એવાં નેક કર્મો કરું જે તને પસંદ હોય, અને મારી સંતાનને પણ નેક બનાવ. હું તારી તરફ તૌબા કરું છું અને હું આજ્ઞાકારીઓમાંથી છું.", "ચાળીસ વર્ષની ઉંમરની કુરઆની દુઆ.", "આભાર, નેક કર્મ અને સંતાનનો સુધાર — બધું એક દુઆમાં."),
        "dua_intimacy" to DuaText("વૈવાહિક સંબંધ પહેલાં", "અલ્લાહના નામથી. હે અલ્લાહ! અમને શૈતાનથી દૂર રાખ અને તું અમને જે (સંતાન) આપે તેને પણ શૈતાનથી દૂર રાખ.", "પતિ-પત્નીના મિલન પહેલાં.", "જો સંતાન નક્કી હોય તો શૈતાન તેને કદી નુકસાન નહીં પહોંચાડે."),
        "dua_ibrahim_children_protection" to DuaText("ઘર અને સંતાનનું રક્ષણ", "હે મારા રબ! આ શહેરને સલામત બનાવ અને મને અને મારી સંતાનને મૂર્તિપૂજાથી બચાવ.", "ઇબ્રાહીમ (અ.) ની દુઆ — શહેર અને સંતાનનું રક્ષણ.", "તૌહીદ પર કાયમ રહેવાની દુઆ."),
        "dua_drinking_milk" to DuaText("દૂધ પીતી વખતે", "હે અલ્લાહ! અમારા માટે તેમાં બરકત આપ અને અમને વધુ આપ.", "દૂધ પીતી વખતે.", "દૂધ ખોરાક અને પીણું બંનેની જગ્યાએ પૂરતું છે."),
        "dua_iftar_host" to DuaText("કોઈને ત્યાં ઇફ્તાર કરતી વખતે", "તમારે ત્યાં રોઝેદારો ઇફ્તાર કરે, નેક લોકો તમારું ભોજન ખાય અને ફરિશ્તાઓ તમારા માટે દુઆ કરે.", "કોઈને ત્યાં ઇફ્તાર કરતી વખતે.", "યજમાન માટે નબી ﷺ ની દુઆ."),
        "dua_seeing_first_fruit" to DuaText("મોસમનું પહેલું ફળ જોઈને", "હે અલ્લાહ! અમારાં ફળોમાં, અમારા શહેરમાં, અમારા સાઅ અને મુદ્દ (માપ-તોલ) માં બરકત આપ.", "મોસમનું પહેલું ફળ જોઈને.", "રોજી અને શહેરમાં બરકતની દુઆ."),
        "dua_good_news" to DuaText("ખુશખબર મળતાં", "બધી પ્રશંસા તે અલ્લાહ માટે જેની કૃપાથી સારાં કામો પૂરાં થાય છે.", "ખુશીના સમાચાર મળતાં (અને સજદાએ શુક્ર).", "નબી ﷺ પસંદગીની વસ્તુ જોઈને આ ફરમાવતા."),
        "dua_looking_mirror" to DuaText("અરીસામાં જોતી વખતે", "હે અલ્લાહ! જેમ તેં મારો ચહેરો સુંદર બનાવ્યો, તેમ મારું ચારિત્ર્ય પણ સુંદર બનાવ.", "અરીસામાં જોતી વખતે.", "નબી ﷺ આ દુઆ કરતા (અરીસાની શરત વિના પણ સાબિત છે)."),
        "dua_rabbana_taqabbal" to DuaText("કર્મોની કબૂલિયત", "હે અમારા રબ! અમારી પાસેથી કબૂલ કર, નિઃશંક તું સાંભળનાર, જાણનાર છે. અને અમારી તૌબા કબૂલ કર, નિઃશંક તું તૌબા કબૂલ કરનાર, દયાળુ છે.", "ઇબ્રાહીમ અને ઇસ્માઈલ (અ.) એ કાબાના નિર્માણ વખતે માગી.", "દરેક નેક કર્મ પછી કબૂલિયતની દુઆ."),
    )
}
